def schema(p):
 u=url(p); item={'@type':p['type'],'@id':u+'#webpage','url':u,'name':p['name'],'description':p['description'],'inLanguage':p['lang'],'isPartOf':{'@id':WEBSITE_ID},'about':{'@id':ORG_ID},'primaryImageOfPage':{'@type':'ImageObject','url':IMAGE}}
