 if p['path'] not in ('','en/'):
  item['breadcrumb']={'@id':u+'#breadcrumb'}; graph.append({'@type':'BreadcrumbList','@id':u+'#breadcrumb','itemListElement':[{'@type':'ListItem','position':1,'name':'GNK ASG','item':SITE},{'@type':'ListItem','position':2,'name':p['crumb'],'item':u}]})
